// Une el texto extraído con notas adicionales y nombre del prospecto
const texto = $input.first().json.content;
const formData = $('Webhook').first().json.body.account;
const nombre =$('Webhook').first().json.body.account ;
const notas = formData['Notas adicionales (opcional)'] || '';

const contenidoCompleto = `PROSPECTO: ${nombre}\n\n` +
  `--- TRANSCRIPCIÓN / RESUMEN ---\n${texto}\n\n` +
  (notas ? `--- NOTAS ADICIONALES ---\n${notas}\n` : '');

return {
  json: {
    prospecto: nombre,
    contenido: contenidoCompleto,
    slug: nombre.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '')
  }
};

// Extrae el JSON de la respuesta de Claude
const response = $input.item.json;

if (!response.content || !Array.isArray(response.content)) {
  throw new Error('Respuesta inesperada de Claude: falta content[]. Payload: ' + JSON.stringify(response).slice(0, 500));
}

const textBlock = response.content.find(b => b.type === 'text');
if (!textBlock) {
  throw new Error('No se encontró bloque de texto en la respuesta de Claude.');
}

let raw = textBlock.text.trim();

// Tolerancia: limpiar fences de markdown si Claude los agregó
if (raw.startsWith('```')) {
  raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
}

let proposalData;
try {
  proposalData = JSON.parse(raw);
} catch (e) {
  throw new Error('Claude no devolvió JSON válido: ' + e.message + '\nPrimeros 500 chars: ' + raw.slice(0, 500));
}

const slug = $('Preparar payload Claude').item.json.slug;

// Detectar si Claude emitió calculadora_inputs (trigger del Excel anexo)
const tieneCalcInputs = !!(proposalData && proposalData.calculadora_inputs &&
  proposalData.calculadora_inputs.unidades_totales &&
  proposalData.calculadora_inputs.ticket_promedio &&
  proposalData.calculadora_inputs.absorcion_meses);
const flagExcel = proposalData && proposalData.genera_excel_anexo === true;
const tieneExcel = tieneCalcInputs && flagExcel;

// Anexar __slug__ al payload del zebra-api
const zebraBody = Object.assign({}, proposalData, { __slug__: slug });

return { json: { zebraBody, slug, tieneExcel } };
